// work.alert.resolve — a cleared alert withdraws its action (Vlad, 4 Nov). Generated by `pnpm gen:command`;
// acceptance cases added.
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { aStaffActor, countRows, runAsOwner } from '@ocs/testing';
import { Forbidden, systemActor, ValidationFailed } from '../../kernel/index.ts';
import { raiseAlert } from '../commands/raise-alert.ts';
import { resolveAlert } from '../commands/resolve-alert.ts';
import { openWorkWorld, type WorkWorld } from './fixture.ts';

const job = systemActor('alerts');
const pm = aStaffActor({ roles: ['pm'] });
let w: WorkWorld;
const reason = 'Device back online';
const resolve = (...refs: string[]) => w.t.kernel.execute(resolveAlert, job, { refs, reason }, 'system');
const status = (ref: string) =>
  ['open', 'done', 'cancelled'].map((s) =>
    countRows(w.testDb.url, `action WHERE source_ref = $1 AND status = $2`, [ref, s]),
  );

beforeAll(async () => {
  w = await openWorkWorld();
  w.t.grant(job, raiseAlert.permission, resolveAlert.permission);
  await runAsOwner(w.testDb.url, `UPDATE site SET pm_id = $2 WHERE id = $1`, [w.siteId, pm.id]);
  const alerts = ['R15:a', 'R15:b', 'R15:c'].map((ref) => ({
    siteId: w.siteId,
    ref,
    title: `${ref} offline`,
  }));
  await w.t.kernel.execute(raiseAlert, job, { alerts }, 'system');
  await runAsOwner(
    w.testDb.url,
    `UPDATE action SET status = 'done', done_at = now() WHERE source_ref = 'R15:b'`,
  );
});

afterAll(async () => {
  await w.close();
});

describe('work.alert.resolve', () => {
  it('refuses anyone but the system actor, and a resolve without a reason', async () => {
    await expect(
      w.t.kernel.execute(resolveAlert, pm, { refs: ['R15:a'], reason }, 'test'),
    ).rejects.toBeInstanceOf(Forbidden);
    await expect(
      w.t.kernel.execute(resolveAlert, job, { refs: ['R15:a'], reason: ' ' }, 'system'),
    ).rejects.toBeInstanceOf(ValidationFailed);
  });

  it('withdraws the open action of a cleared alert; a done one and other alerts stay as they are', async () => {
    const r = await resolve('R15:a', 'R15:b', 'R15:unknown');
    expect(r.withdrawn.map((x) => x.ref)).toEqual(['R15:a']);
    expect(await Promise.all(status('R15:a'))).toEqual([0, 0, 1]);
    expect(await Promise.all(status('R15:b'))).toEqual([0, 1, 0]);
    expect(await Promise.all(status('R15:c'))).toEqual([1, 0, 0]);
    expect(await countRows(w.testDb.url, `outbox WHERE event_type = 'work.action.cancelled'`)).toBe(1);
  });

  it('resolving again changes nothing (idempotent)', async () => {
    expect((await resolve('R15:a')).withdrawn).toEqual([]);
  });

  it('a summary alert is superseded: older refs with the prefix go, the current one stays', async () => {
    const recon = ['RECON:s1:aaa', 'RECON:s1:bbb', 'RECON:s2:ccc'];
    const alerts = recon.map((ref) => ({ siteId: w.siteId, ref, title: ref }));
    await w.t.kernel.execute(raiseAlert, job, { alerts }, 'system');
    const r = await w.t.kernel.execute(
      resolveAlert,
      job,
      {
        refs: [],
        reason: 'Reconciliation changed',
        superseded: { prefix: 'RECON:s1:', keep: 'RECON:s1:bbb' },
      },
      'system',
    );
    expect(r.withdrawn.map((x) => x.ref)).toEqual(['RECON:s1:aaa']);
    const none = await w.t.kernel.execute(
      resolveAlert,
      job,
      { refs: [], reason: 'Reconciled', superseded: { prefix: 'RECON:s1:', keep: null } },
      'system',
    );
    expect(none.withdrawn.map((x) => x.ref)).toEqual(['RECON:s1:bbb']);
    expect(await Promise.all(status('RECON:s2:ccc'))).toEqual([1, 0, 0]);
  });
});
